import json

cities = []

def add(id, name, type_, prov, island, lat, lng, pop, coastal, facing=None):
    entry = {
        "id": id,
        "name": name,
        "type": type_,
        "province": prov,
        "islandGroup": island,
        "lat": round(lat, 4),
        "lng": round(lng, 4),
        "population": pop,
        "isCoastal": coastal,
    }
    if coastal and facing:
        entry["coastalFacing"] = facing
    cities.append(entry)

